const value = applyCast(data.pre, data.src);
return out(safeSplit(value, data.sep));
*/
// ===============================================================================
// safeSplit(...) – Apply Mode
// ===============================================================================
return function(value, separator) {
   separator = data.rp1 ? separator : data.sep;
   return out(safeSplit(value, separator));
};


